,"description":"2016.05.30_KBS Cool FM 89.1MHz (월~일) 밤 12:00~02:00\n유지원의 옥탑방 라디오 http://www.kbs.co.kr/radio/coolfm/yourooftop/\n특별 초대석 with 루나","published_at":"2016-06-05","group_ko":"에프엑스","members":[],"with_groups":[],"with_members":[],"cover_of_groups":[],"cover_of_members":[],"source_handle":"KBS_CoolFM","tags_manual":false,"content_flag":null}}]$plan$::jsonb)
 LOOP
  SELECT * INTO current_row FROM public.yt_channel_videos WHERE id=p->'before'->>'id' FOR UPDATE;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM jsonb_each(p->'before') e WHERE (to_jsonb(current_row)->e.key) IS DISTINCT FROM e.value) THEN
   RAISE EXCEPTION 'Snapshot mismatch for %; no changes applied',p->'before'->>'id';
  END IF;
  next_row:=jsonb_populate_record(NULL::public.yt_channel_videos,p->'after');
  IF current_row.tags_manual THEN UPDATE public.yt_channel_videos SET tags_manual=false WHERE id=current_row.id; END IF;
  UPDATE public.yt_channel_videos SET group_ko=next_row.group_ko,members=next_row.members,
   with_groups=next_row.with_groups,with_members=next_row.with_members,
   cover_of_groups=next_row.cover_of_groups,cover_of_members=next_row.cover_of_members,tags_manual=next_row.tags_manual,content_flag=next_row.content_flag
   WHERE id=current_row.id;
 END LOOP;
END $audit$;
COMMIT;
